  setRequestLocale((await params).locale)
  const t = await getTranslations("Auth")

  return (
    <main className="mx-auto flex w-full max-w-md flex-1 flex-col gap-6 px-4 py-10 sm:py-16">
      <div className="flex flex-col gap-1">
        <h1 className="text-2xl font-semibold tracking-tight">{t("login_title")}</h1>
        <p className="text-sm text-muted-foreground">{t("login_description")}</p>
      </div>
      <LoginForm />
    </main>
  )
}

