import { REGISTER_PATH } from "@/features/auth/constants/auth.constants"
import { renderWithProviders } from "@/test/render"
import { server } from "@/test/server"

// next-intl's navigation imports `next/navigation` in a way Vitest cannot resolve, and the tests
// only need the link's markup.
vi.mock("@/i18n/routing", () => ({
  Link: ({ href, ...props }: ComponentProps<"a"> & { href: string }) => <a href={href} {...props} />
}))

const REGISTER_URL = `${siteConfig.apiUrl}${REGISTER_PATH}`
const PASSWORD = "velvet-river-compass-7"

/** DummyJSON's `/users/add`: it echoes what it was sent, the password too, with a new id. */
function serveRegister() {
  const bodies: unknown[] = []
  server.use(
    http.post(REGISTER_URL, async ({ request }) => {
      const body: unknown = await request.json()
      bodies.push(body)
      return HttpResponse.json({ ...Object(body), id: 209 }, { status: 201 })
    })
  )
  return bodies
}

async function renderRegister() {
  renderWithProviders(<RegisterForm />)
  return screen.findByLabelText("First name")
}

async function fillDetails(user: UserEvent) {
  await user.type(screen.getByLabelText("First name"), "Ada")
  await user.type(screen.getByLabelText("Last name"), "Lovelace")
  await user.type(screen.getByLabelText("Username"), "ada.lovelace")
  await user.type(screen.getByLabelText("Email"), "ada@example.com")
}

async function fillAndSubmit(user: UserEvent, password = PASSWORD, confirm = password) {
  await fillDetails(user)
  await user.type(screen.getByLabelText("Password"), password)
  await user.type(screen.getByLabelText("Confirm password"), confirm)
  await user.click(screen.getByRole("button", { name: "Create account" }))
}

describe("RegisterForm", () => {
  it("shows every error and sends nothing while the input is invalid", async () => {
    const bodies = serveRegister()
    const user = userEvent.setup()
    await renderRegister()

    await user.type(screen.getByLabelText("Username"), "not valid")
    await user.type(screen.getByLabelText("Email"), "ada@")
    await user.click(screen.getByRole("button", { name: "Create account" }))

    expect(await screen.findByText("Enter your first name")).toBeInTheDocument()
    expect(screen.getByText("Enter your last name")).toBeInTheDocument()
    expect(screen.getByText(/Use letters, numbers/)).toBeInTheDocument()
    expect(screen.getByText("Enter a valid email address")).toBeInTheDocument()
    expect(screen.getByText("Use at least 15 characters")).toBeInTheDocument()
    // The error joins the strength in the field's description; it does not replace it.
    const password = screen.getByLabelText("Password")
    expect(password).toHaveAccessibleDescription(/Use at least 15 characters/)
    expect(password).toHaveAccessibleDescription(/Choose a long password/)
    expect(bodies).toHaveLength(0)
  })

  it("scores the password as it is typed and ticks the rules it meets", async () => {
    const user = userEvent.setup()
    await renderRegister()
    const password = screen.getByLabelText("Password")
    expect(password).toHaveAttribute("autocomplete", "new-password")

    await user.type(password, "short")
    expect(screen.getByText("Strength: Weak")).toHaveAttribute("role", "status")
    expect(screen.getByText("15 to 64 characters")).toHaveTextContent("Not met:")

    await user.clear(password)
    await user.type(password, PASSWORD)
    expect(screen.getByText("Strength: Good")).toBeInTheDocument()
    expect(screen.getByText("15 to 64 characters")).toHaveTextContent("Met:")
    expect(password).toHaveAccessibleDescription(/Strength: Good/)
  })

  it("turns down a common password, one made of the name, and a confirmation that differs", async () => {
    const bodies = serveRegister()
    const user = userEvent.setup()
    await renderRegister()

    await fillAndSubmit(user, "lovelace-lovelace-1815", "lovelace-lovelace-1816")
    expect(await screen.findByText("Don't use your name, username or email")).toBeInTheDocument()
    expect(screen.getByText("The passwords don't match")).toBeInTheDocument()

    await user.clear(screen.getByLabelText("Password"))
    await user.type(screen.getByLabelText("Password"), "password12345678")
    await user.click(screen.getByRole("button", { name: "Create account" }))
    expect(await screen.findByText("This password is too common")).toBeInTheDocument()
    expect(bodies).toHaveLength(0)
  })

  it("shows the returned account, says it was not saved, and keeps the password out of it", async () => {
    const bodies = serveRegister()
    const user = userEvent.setup()
    await renderRegister()

    await fillAndSubmit(user)

    const result = await screen.findByRole("status")
    expect(result).toHaveTextContent("user #209")
    expect(result).toHaveTextContent("Ada Lovelace")
    expect(result).toHaveTextContent("@ada.lovelace")
    expect(result).toHaveTextContent(/not saved/i)
    expect(screen.getByRole("link", { name: "Go to sign in" })).toHaveAttribute("href", "/login")
    expect(bodies).toEqual([
      {
        firstName: "Ada",
        lastName: "Lovelace",
        username: "ada.lovelace",
        email: "ada@example.com",
        password: PASSWORD
      }
    ])
    expect(document.body.innerHTML).not.toContain(PASSWORD)
  })

  it("starts over with an empty form", async () => {
    serveRegister()
    const user = userEvent.setup()
    await renderRegister()

    await fillAndSubmit(user)
    await user.click(await screen.findByRole("button", { name: "Create another account" }))

    expect(screen.getByLabelText("First name")).toHaveValue("")
    expect(screen.getByLabelText("Password")).toHaveValue("")
  })

  it("keeps the input and shows an error when the request fails", async () => {
    server.use(http.post(REGISTER_URL, () => HttpResponse.json({}, { status: 500 })))
    const user = userEvent.setup()
    await renderRegister()

    await fillAndSubmit(user)

    expect(await screen.findByText(/Could not create the account/)).toBeInTheDocument()
    expect(screen.getByLabelText("First name")).toHaveValue("Ada")
  })

  it("links to the sign-in page", async () => {
    await renderRegister()

    expect(screen.getByRole("link", { name: "Sign in" })).toHaveAttribute("href", "/login")
  })
})

"use client"

import { useState } from "react"
import type { ReactNode } from "react"

import { EyeIcon, EyeOffIcon } from "lucide-react"
import { zodResolver } from "@hookform/resolvers/zod"
import { useViraPassword } from "@virastack/password"
import { useTranslations } from "next-intl"
import { useForm, useWatch } from "react-hook-form"

import { Button } from "@/components/ui/button"
import { Field, FieldError, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { AuthLink } from "@/features/auth/components/AuthLink"
import { PasswordInput } from "@/features/auth/components/PasswordInput"
import { PasswordStrength } from "@/features/auth/components/PasswordStrength"
import { RegisterSuccess } from "@/features/auth/components/RegisterSuccess"
import { LOGIN_ROUTE, PASSWORD_POLICY } from "@/features/auth/constants/auth.constants"
import { useRegister } from "@/features/auth/hooks/use-register"
import { createRegisterFormSchema } from "@/features/auth/schemas/auth.schema"
import type { RegisteredUser, RegisterFormInput } from "@/features/auth/schemas/auth.schema"

const EMPTY_VALUES: RegisterFormInput = {
  firstName: "",
  lastName: "",
  username: "",
  email: "",
  password: "",
  confirmPassword: ""
}

const ICONS = { show: <EyeIcon aria-hidden />, hide: <EyeOffIcon aria-hidden /> }

type TextFieldName = Exclude<keyof RegisterFormInput, "password" | "confirmPassword">

export function RegisterForm() {
  const t = useTranslations("Auth")
  const registerAccount = useRegister()
  const [created, setCreated] = useState<RegisteredUser | null>(null)
  const form = useForm<RegisterFormInput>({
    resolver: zodResolver(createRegisterFormSchema(t)),
    defaultValues: EMPTY_VALUES
  })
  const { errors, isSubmitting } = form.formState
  // From `useWatch`, so the strength follows `setValue` and `reset` too.
  const [password, confirmPassword, firstName, lastName, username, email] = useWatch({
    control: form.control,
    name: ["password", "confirmPassword", "firstName", "lastName", "username", "email"]
  })
  const newPassword = useViraPassword({
    id: "password",
    policy: PASSWORD_POLICY,
    value: password,
    forbidden: [firstName, lastName, username, email],
    icons: ICONS,
    btnProps: { "aria-label": t("show_password") },
    inputProps: {
      "aria-invalid": Boolean(errors.password),
      // Only with an error, which the hook adds to the strength's id: an `undefined` would
      // replace it.
      ...(errors.password && { "aria-describedby": "password-error" })
    }
  })
  const confirm = useViraPassword({
    id: "confirmPassword",
    matchWith: password,
    value: confirmPassword,
    icons: ICONS,
    btnProps: { "aria-label": t("show_confirm_password") },
    inputProps: {
      "aria-invalid": Boolean(errors.confirmPassword),
      ...(errors.confirmPassword && { "aria-describedby": "confirmPassword-error" })
    }
  })

  const onSubmit = form.handleSubmit(async (input) => {
    try {
      setCreated(await registerAccount.mutateAsync(input))
      // The form stays mounted under the result, so the password leaves it now.
      form.reset(EMPTY_VALUES)
    } catch {
      form.setError("root.server", { message: t("error_register") })
    } finally {
      // The mutation's variables hold the password: drop them once the answer is in.
      registerAccount.reset()
    }
  })

  if (created) return <RegisterSuccess user={created} onReset={() => setCreated(null)} />

  const textField = (name: TextFieldName, label: string, autoComplete: string): ReactNode => {
    const error = errors[name]?.message

    return (
      <Field data-invalid={Boolean(error)}>
        <FieldLabel htmlFor={name}>{label}</FieldLabel>
        <Input
          {...form.register(name)}
          id={name}
          type={name === "email" ? "email" : "text"}
          autoComplete={autoComplete}
          aria-invalid={Boolean(error)}
          aria-describedby={error ? `${name}-error` : undefined}
        />
        {error ? <FieldError id={`${name}-error`}>{error}</FieldError> : null}
      </Field>
    )
  }

  return (
    <div className="flex flex-col gap-6">
      {/* `post`: before hydration the browser submits natively, and a GET puts the password in the URL. */}
      <form method="post" onSubmit={onSubmit} noValidate className="flex flex-col gap-4">
        <div className="grid gap-4 sm:grid-cols-2">
          {textField("firstName", t("field_first_name"), "given-name")}
          {textField("lastName", t("field_last_name"), "family-name")}
        </div>
        {textField("username", t("field_username"), "username")}
        {textField("email", t("field_email"), "email")}
        <Field data-invalid={Boolean(errors.password)}>
          <FieldLabel htmlFor="password">{t("field_password")}</FieldLabel>
          <PasswordInput
            {...form.register("password", { deps: ["confirmPassword"] })}
            password={newPassword}
            capsLockHint={t("caps_lock")}
          />
          {errors.password ? (
            <FieldError id="password-error">{errors.password.message}</FieldError>
          ) : null}
          <PasswordStrength
            strength={newPassword.strength}
            strengthProps={newPassword.strengthProps}
          />
        </Field>
        <Field data-invalid={Boolean(errors.confirmPassword)}>
          <FieldLabel htmlFor="confirmPassword">{t("field_confirm_password")}</FieldLabel>
          <PasswordInput
            {...form.register("confirmPassword")}
            password={confirm}
            capsLockHint={t("caps_lock")}
          />
          {errors.confirmPassword ? (
            <FieldError id="confirmPassword-error">{errors.confirmPassword.message}</FieldError>
          ) : null}
        </Field>
        {errors.root?.server ? (
          <p role="alert" className="text-sm text-destructive">
            {errors.root.server.message}
          </p>
        ) : null}
        <Button type="submit" disabled={isSubmitting}>
          {isSubmitting ? t("creating_account") : t("create_account")}
        </Button>
      </form>
      <p className="text-center text-sm text-muted-foreground">
        {t("have_account")}{" "}
        <AuthLink
          href={LOGIN_ROUTE}
          className="font-medium text-foreground underline underline-offset-4"
        >
          {t("sign_in")}
        </AuthLink>
      </p>
    </div>
  )
}

